/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `after_devolucion_completada` AFTER UPDATE ON `cambios_ventas` FOR EACH ROW BEGIN
    IF NEW.estado = 'completado' AND OLD.estado != 'completado' AND NEW.tipo = 'devolucion' THEN
        UPDATE productos p
        JOIN detalle_ventas dv ON p.id_producto = dv.id_producto
        JOIN cambios_ventas cv ON dv.id_venta = cv.id_venta_original
        SET p.stock = p.stock + dv.cantidad
        WHERE cv.id_cambio = NEW.id_cambio;
    END IF;
